package com.hbm.worldgen.oil;
import com.hbm.block.oilplant.*;
import com.hbm.block.ore.LegacyOreBlock;
import com.hbm.block.falling.LegacyFallingBlock;
import com.hbm.config.WorldgenControls;
import com.hbm.world.structure.NaturalStructures;
import com.hbm.world.structure.StructureSurfaceBiomes;
import java.util.Random;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.feature.*;
import net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration;
/** The three actual HbmWorld MapGenChainloader oil terrains. Each virtual source is clipped to this chunk. */
public final class OilGeologyFeature extends Feature<NoneFeatureConfiguration> {
 public OilGeologyFeature(){super(NoneFeatureConfiguration.CODEC);}
 @Override public boolean place(FeaturePlaceContext<NoneFeatureConfiguration> context){var level=context.level();if(!level.getLevel().dimension().equals(Level.OVERWORLD))return false;var target=new ChunkPos(context.origin());boolean crater=com.hbm.worldgen.naturalevents.SourceRadiationHotspots.place(level,target);if(!WorldgenControls.oreFeature("oil_terrain"))return crater;var field=new Field(level,target);for(int kind=0;kind<3;kind++){String name=new String[]{"oil_bubbles","bedrock_oil","oil_sand"}[kind];var control=WorldgenControls.rule("oil_terrain",name);if(!control.enabled())continue;int frequency=control.chance(kind==0?100:200);if(frequency<=0)continue;int range=kind==0?3:kind==1?4:7;var seed=new Random(level.getSeed());long xSeed=seed.nextLong(),zSeed=seed.nextLong();for(int ox=target.x-range;ox<=target.x+range;ox++)for(int oz=target.z-range;oz<=target.z+range;oz++){var random=new Random((long)ox*xSeed^(long)oz*zSeed^level.getSeed());if(kind==1)bedrock(field,random,ox,oz,frequency,control);else bubble(field,random,ox,oz,kind==2,frequency,control);}}return field.changed>0||crater;}
 private static final class Field {final WorldGenLevel level;final ChunkPos chunk;int changed;Field(WorldGenLevel level,ChunkPos chunk){this.level=level;this.chunk=chunk;}BlockPos pos(int x,int y,int z){return new BlockPos(chunk.getMinBlockX()+x,y,chunk.getMinBlockZ()+z);}BlockState get(int x,int y,int z){return y<level.getMinBuildHeight()||y>=level.getMaxBuildHeight()?Blocks.AIR.defaultBlockState():level.getBlockState(pos(x,y,z));}void set(int x,int y,int z,BlockState state){if(y<level.getMinBuildHeight()||y>=level.getMaxBuildHeight())return;if(level.setBlock(pos(x,y,z),state,2))changed++;}int min(){return level.getMinBuildHeight();}int max(){return level.getMaxBuildHeight()-1;}}
 private static BlockState state(String name){var id=ResourceLocation.parse("hbm:"+name);if(!BuiltInRegistries.BLOCK.containsKey(id))throw new IllegalStateException("Missing actual oil terrain block "+id);return BuiltInRegistries.BLOCK.get(id).defaultBlockState();}
 private static BlockState dead(int meta){return state("plant_dead").setValue(LegacyOreBlock.LEGACY_META,meta);}
 private static boolean stone(BlockState state){return state.is(Blocks.STONE)||state.is(Blocks.DEEPSLATE);}
 private static boolean sand(BlockState s){return s.is(Blocks.SAND)||s.is(Blocks.RED_SAND)||s.is(state("ore_oil_sand").getBlock());}
 private static boolean dirt(BlockState s){return s.is(Blocks.GRASS_BLOCK)||s.is(Blocks.DIRT);}
 private static void bubble(Field field,Random random,int ox,int oz,boolean oilSand,int frequency,WorldgenControls.Rule control){var holder=StructureSurfaceBiomes.sample(field.level,ox*16,oz*16);var profile=NaturalStructures.profile(holder);float temperature=profile==null?holder.value().getBaseTemperature():profile.temperature(),rainfall=profile==null?holder.value().getModifiedClimateSettings().downfall():profile.rainfall();boolean lightning=profile==null?holder.value().hasPrecipitation()&&temperature>=.15F:profile.lightning();int effective=frequency;if(temperature>=2&&rainfall<.1)effective/=3;if(effective<=0)effective=1;if(random.nextInt(effective)!=effective-1||oilSand&&(lightning||temperature<1.5F))return;int xCoord=(field.chunk.x-ox)*16+random.nextInt(16),zCoord=(field.chunk.z-oz)*16+random.nextInt(16);int low=control.integer("minY",oilSand?56:15),high=Math.max(low,control.integer("maxY",oilSand?71:39));int center=random.nextInt(high-low+1)+low;double radius=random.nextInt(oilSand?32:8)+(oilSand?16:8),radiusSquared=radius*radius/2;int min=Math.max(field.min()+1,(int)Math.floor(center-radius)),max=Math.min(field.max(),(int)Math.ceil(center+radius));var output=state(oilSand?"ore_oil_sand":"ore_oil");for(int x=15;x>=0;x--)for(int z=15;z>=0;z--)for(int y=min;y<max;y++){var old=field.get(x,y,z);if(oilSand?old.is(Blocks.SAND)||old.is(Blocks.RED_SAND):stone(old)){int a=xCoord+x,b=zCoord+z,c=center-y;double distance=a*a+b*b+c*c*3;if(oilSand)distance-=random.nextDouble()*radiusSquared/3;if(distance<radiusSquared)field.set(x,y,z,oilSand&&old.is(Blocks.RED_SAND)?output.setValue(LegacyFallingBlock.LEGACY_META,1):output);}}if(random.nextInt(1)==0&&WorldgenControls.oilSurfaceIndicators())surface(field,random,xCoord,zCoord,false);}
 private static void bedrock(Field field,Random random,int ox,int oz,int frequency,WorldgenControls.Rule control){if(random.nextInt(frequency)!=frequency-2)return;int xCoord=(field.chunk.x-ox)*16+random.nextInt(16),zCoord=(field.chunk.z-oz)*16+random.nextInt(16);int bottom=control.integer("minY",field.min()),top=control.integer("maxY",bottom+4);for(int x=15;x>=0;x--)for(int z=15;z>=0;z--)for(int y=bottom;y<=top;y++){var old=field.get(x,y,z);if(stone(old)||old.is(Blocks.BEDROCK)){int a=xCoord+x,b=zCoord+z,c=y-bottom;if(Math.abs(a)<5&&Math.abs(b)<5&&Math.abs(a)+Math.abs(c)+Math.abs(b)<=6)field.set(x,y,z,state("ore_bedrock_oil"));}}if(WorldgenControls.oilSurfaceIndicators())surface(field,random,xCoord,zCoord,true);}
 private static void surface(Field field,Random random,int centerX,int centerZ,boolean bedrock){int count=bedrock?50:150,width=bedrock?5:7;for(int i=0;i<count;i++){int offX=(int)(random.nextGaussian()*width),offZ=(int)(random.nextGaussian()*width),x=offX-centerX,z=offZ-centerZ;if(x<0||x>=16||z<0||z>=16)continue;for(int y=field.max();y>=field.min();y--){var ground=field.get(x,y,z);if(!ground.canOcclude())continue;for(int offset=1;offset> -3;offset--){var old=field.get(x,y+offset,z);if(dirt(old)){if(bedrock)field.set(x,y+offset,z,state(random.nextInt(10)==0?"dirt_oily":"dirt_dead"));else{boolean inner=offX*offX+offZ*offZ<(width/2)*(width/2);field.set(x,y+offset,z,state(inner?"dirt_oily":"dirt_dead"));}
 if(bedrock&&offset==0&&random.nextInt(50)==0)field.set(x,y+offset+1,z,OilBotanyContent.FLOWER.get().defaultBlockState().setValue(OilFlowerBlock.META,4));
 boolean outer=offX*offX+offZ*offZ>=(width/2)*(width/2);if((bedrock||outer)&&offset==0&&random.nextInt(20)==0)field.set(x,y+offset+1,z,dead(random.nextInt(5)));break;}
 if(sand(old)){field.set(x,y+offset,z,state(old.is(Blocks.RED_SAND)||old.is(state("ore_oil_sand").getBlock())&&old.getValue(LegacyFallingBlock.LEGACY_META)==1?"sand_dirty_red":"sand_dirty"));break;}if(stone(old)){field.set(x,y+offset,z,state("stone_cracked"));break;}}
 break;}}
 if(bedrock)return;for(int i=1;i<6;i++){var direction=Direction.from3DDataValue(i);int x=direction.getStepX()-centerX,z=direction.getStepZ()-centerZ;if(x<0||x>=16||z<0||z>=16)continue;int solids=0;for(int y=field.max();y>=field.min();y--){var old=field.get(x,y,z);if(!old.getFluidState().isEmpty())break;if(old.canOcclude()){solids++;if(i>1){field.set(x,y,z,state("stone_cracked"));if(solids>=4)break;}else{if(solids<3)field.set(x,y,z,Blocks.AIR.defaultBlockState());if(solids==3)field.set(x,y,z,state("oil_spill"));if(solids>3&&solids<7)field.set(x,y,z,state("stone_cracked"));if(solids>=7)break;}}}}}
}
